package vn.edu.eaut.lab9.service; import vn.edu.eaut.lab9.model.*;import vn.edu.eaut.lab9.repository.*;import java.util.*; public class SinhVienService{private final SinhVienRepository repo=new SinhVienRepository();private final LopHocRepository lopRepo=new LopHocRepository();public List<SinhVien> list(String q,int p){return repo.search(q==null?"":q,p);}public long pages(String q){return (repo.count(q==null?"":q)+4)/5;}public SinhVien find(int id){return repo.findById(id);}public List<LopHoc> classes(){return lopRepo.findAll();}public void save(SinhVien s){validate(s);repo.save(s);}public void update(SinhVien s){validate(s);repo.update(s);}public void delete(int id){repo.delete(id);}private void validate(SinhVien s){if(s.getMaSinhVien()==null||s.getMaSinhVien().isBlank()||s.getHoTen()==null||s.getHoTen().isBlank())throw new IllegalArgumentException("Mã sinh viên và họ tên là bắt buộc");if(s.getEmail()!=null&&!s.getEmail().isBlank()&&!s.getEmail().matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Email không hợp lệ");}}
